-- Park & Shop
DELETE FROM projectTags WHERE projectId = (SELECT id FROM projects WHERE slug = 'park-shop');
INSERT INTO projectTags (projectId, tagId)
SELECT p.id, t.id FROM projects p CROSS JOIN tags t
WHERE p.slug = 'park-shop'
AND t.name IN ('Dystopian', 'Industrial', 'Contemporary Drama', 'Summer Stock', '2024');

